def icon(name: str, size: int = 16, color: str = "currentColor", stroke: float = 2.0) -> str:
    """Inline ``<svg>`` for Lucide icon ``name`` (px ``size``), vertically aligned with surrounding text."""
    return (f'<svg class="lucide" xmlns="http://www.w3.org/2000/svg" width="{size}" height="{size}" viewBox="0 0 24 24" '
            f'fill="none" stroke="{color}" stroke-width="{stroke}" stroke-linecap="round" stroke-linejoin="round" '
            f'style="vertical-align:-0.15em;margin-right:.35em;flex-shrink:0">{_SHAPES[name]}</svg>')


NAMES = tuple(_SHAPES)

if __name__ == "__main__":
    print(f"{len(NAMES)} Lucide icons:", ", ".join(NAMES))
    print(icon("satellite"))
